{
    int value = 10;
    int *ptr_value = &value;
    int **ptr_ptr_value = &ptr_value;

    std::cout << "Gia tri cua 'value': " << value << std::endl; // 10

    std::cout << "Dia chi cua 'value': " << &value << std::endl;
    std::cout << "Gia tri cua 'ptr_value' (dia chi 'value'): " << ptr_value << std::endl;
    std::cout << "Gia tri ma 'ptr_value' tro toi: " << *ptr_value << std::endl; // 10

    std::cout << "Dia chi cua 'ptr_value': " << &ptr_value << std::endl;
    std::cout << "Gia tri cua 'ptr_ptr_value' (dia chi 'ptr_value'): " << ptr_ptr_value << std::endl;
    std::cout << "Gia tri ma '*ptr_ptr_value' tro toi (dia chi 'value'): " << *ptr_ptr_value << std::endl; // ptr_value
    std::cout << "Gia tri ma '**ptr_ptr_value' tro toi (gia tri 'value'): " << **ptr_ptr_value << std::endl; // 10

    return 0;
}
